import{_ as t}from"./chunks/console-qa-feedback.De5dX-GL.js";import{_ as o,o as r,c as a,a3 as s}from"./chunks/framework.DhF4LrUq.js";const f=JSON.parse('{"title":"Triage tester feedback","description":"Triage tester feedback - classify severity, assign owners, resolve or reject with a note, and watch the open-critical gate respond.","frontmatter":{"description":"Triage tester feedback - classify severity, assign owners, resolve or reject with a note, and watch the open-critical gate respond."},"headers":[],"relativePath":"how-to/console/feedback-triage.md","filePath":"how-to/console/feedback-triage.md"}'),i={name:"how-to/console/feedback-triage.md"};function n(c,e,h,l,d,p){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="triage-tester-feedback" tabindex="-1">Triage tester feedback <a class="header-anchor" href="#triage-tester-feedback" aria-label="Permalink to &quot;Triage tester feedback&quot;">​</a></h1><p>Every report testers submit from the <a href="/shipperdog/snapshot/how-to/portal/feedback">Portal</a> lands in the <strong>Feedback</strong> block of the <a href="/shipperdog/snapshot/how-to/console/releases">release dashboard</a>, with the context they never had to type attached. Triage is the working of that queue — and a triage act here is what unblocks a promotion there.</p><p><img src="'+t+'" alt="Tester feedback on the release dashboard"></p><p>How feedback flows into metrics and gates is covered in <a href="/shipperdog/snapshot/concepts/feedback-analytics">feedback and analytics</a>.</p><h2 id="read-the-queue" tabindex="-1">Read the queue <a class="header-anchor" href="#read-the-queue" aria-label="Permalink to &quot;Read the queue&quot;">​</a></h2><p>The headline states the standing — <code>14 reports · 1 critical open</code> — with the per-severity and per-status chips beneath. Each row shows the report type, status, submitting tenant, and moment. <strong>Details</strong> expands the description, the device context (auto-attached when the tester&#39;s registered device reported it), attachments, and any resolution note.</p><h2 id="work-a-report" tabindex="-1">Work a report <a class="header-anchor" href="#work-a-report" aria-label="Permalink to &quot;Work a report&quot;">​</a></h2><ol><li><p><strong>Classify</strong> — the <strong>Severity</strong> selector on the row sets <code>critical</code>, <code>major</code>, or <code>minor</code>. Classification is the triage act: it moves the open-critical count the moment you set it.</p></li><li><p><strong>Assign</strong> — the <strong>Assignee</strong> field picks an owner from your organization&#39;s roster.</p></li><li><p><strong>Move the lifecycle</strong> — only the legal edges are offered:</p><ul><li>An <strong>OPEN</strong> report: <strong>Triage</strong> (you have looked at it).</li><li>A <strong>TRIAGED</strong> report: <strong>Resolve</strong> or <strong>Reject</strong> — both open a dialog with a required note (the resolution note, or the reason it is not a bug).</li><li>A closed report: <strong>Re-open</strong> when it comes back.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">The promotion connection</p><p>The <code>open-critical-bugs</code> gate reads this block&#39;s open-critical count live: resolve or re-open a report and the next promotion attempt re-evaluates. A critical open blocks promotion — resolve the bug instead of overriding the gate whenever you can. See <a href="/shipperdog/snapshot/how-to/console/quality-gates">quality gates</a>.</p></div><h2 id="security-reports" tabindex="-1">Security reports <a class="header-anchor" href="#security-reports" aria-label="Permalink to &quot;Security reports&quot;">​</a></h2><p>Reports testers file as <em>Security issue</em> are visible only to the team members cleared to handle security — the restricted visibility is automatic on the <a href="/shipperdog/snapshot/how-to/portal/feedback">portal side</a>, and the same restriction follows the report here.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/portal/feedback">submit feedback (tester view)</a> · <a href="/shipperdog/snapshot/how-to/console/quality-gates">quality gates</a> · <a href="/shipperdog/snapshot/roles/qa-engineer">qa-engineer quickstart</a></p>',12)])])}const b=o(i,[["render",n]]);export{f as __pageData,b as default};
